import{bV as o,aL as t,u as d,G as c}from"./chunks/framework.ExNI9tDi.js";const p=JSON.parse('{"title":"模块简介","description":"","frontmatter":{"date":"2026-08-06T22:22:34.000Z","title":"模块简介","permalink":"/pages/opencv","categories":["接口"]},"headers":[],"relativePath":"01.接口/50.高级接口/117.OpencvOps_图像处理/01.模块简介.md","filePath":"01.接口/50.高级接口/117.OpencvOps_图像处理/01.模块简介.md","lastUpdated":null}'),a={name:"01.接口/50.高级接口/117.OpencvOps_图像处理/01.模块简介.md"};function r(n,e,l,s,i,g){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="模块简介" tabindex="-1">模块简介 <a class="header-anchor" href="#模块简介" aria-label="Permalink to &quot;模块简介&quot;">​</a></h1><h2 id="模块简介-1" tabindex="-1">模块简介 <a class="header-anchor" href="#模块简介-1" aria-label="Permalink to &quot;模块简介&quot;">​</a></h2><p><code>OpencvOps</code> 提供常用图像预处理能力。</p><ul><li><strong>系统要求</strong>：Android 7.0+（minSdk 24）</li></ul><h2 id="功能概览" tabindex="-1">功能概览 <a class="header-anchor" href="#功能概览" aria-label="Permalink to &quot;功能概览&quot;">​</a></h2><ul><li><strong>统一转换</strong>：<code>bitmapToMat(bitmap)</code> —— Bitmap 转 Mat 句柄（入口）</li><li><strong>读取文件</strong>：<code>readResMat(path)</code> —— 从图片文件读取为 Mat</li><li><strong>尺寸查询</strong>：<code>getWidth(matId)</code> / <code>getHeight(matId)</code> —— 获取 Mat 宽高</li><li><strong>灰度处理</strong>：<code>matToGray(matId)</code> —— 彩色图转单通道灰度图</li><li><strong>二值化处理</strong>：<code>matThreshold(matId, thresh, maxval, type)</code> —— 固定阈值二值化</li><li><strong>双阈值二值化</strong>：<code>matDoubleThreshold(matId, lowThresh, highThresh, maxval)</code> —— 区间保留二值化</li><li><strong>自适应二值化</strong>：<code>matAdaptiveThreshold(matId, maxValue, adaptiveMethod, thresholdType, blockSize, c)</code> —— 局部自适应二值化</li><li><strong>颜色空间转换</strong>：<code>getHSV(matId, type)</code> / <code>getHLS(matId, type)</code> / <code>getBGR(matId, type)</code> —— 全图或单通道</li><li><strong>像素平均值</strong>：<code>getBGRAverage(matId, type)</code> —— 获取 BGR 各通道像素平均值</li><li><strong>边缘检测</strong>：<code>findCannys(matId, threshold1, threshold2, apertureSize, L2gradient)</code> —— Canny 边缘检测</li><li><strong>形状检测</strong>：<code>findLines</code> / <code>findCircles</code> / <code>findPolygons</code>（二值图轻量入口）/ <code>findPolygonsEx</code>（任意图增强入口） —— 直线 / 圆 / 凸包形状检测</li><li><strong>凸包</strong>：<code>getConvexHull</code> / <code>isContourConvex</code></li><li><strong>轮廓处理</strong>：<code>getContours</code> / <code>getContoursRect</code> / <code>getContoursCircles</code> / <code>getContoursLength</code> / <code>getContoursArea</code> / <code>getContoursHierarchy</code> / <code>getContoursMoments</code></li><li><strong>形态学操作</strong>：<code>dilate</code> / <code>erode</code> / <code>open</code> / <code>close</code> / <code>topHat</code> / <code>blackHat</code> / <code>gradient</code> / <code>skeleton</code></li><li><strong>滤波 / 像素运算</strong>：<code>absDiff</code> / <code>bitwiseOr</code> / <code>medianBlur</code> / <code>gaussianBlur</code> / <code>blur</code> / <code>bilateral</code> / <code>filter2D</code></li><li><strong>颜色范围 / 掩膜</strong>：<code>inRange</code> / <code>copyTo</code></li><li><strong>区域操作</strong>：<code>cropMat</code>（裁剪） / <code>drawRect</code> / <code>drawRects</code>（画框） / <code>findImg</code>（模板匹配找图）</li><li><strong>梯度形状匹配</strong>：<code>loadYaml</code> / <code>matchGradientShape</code> / <code>releaseYaml</code> / <code>getYamlNames</code></li><li><strong>几何变换</strong>：<code>warpPerspective</code>（透视变换）</li><li><strong>投影与计数</strong>：<code>projection</code> / <code>projectionValue</code>（行 / 列投影）/ <code>countNonZero</code> / <code>countNonZeroRect</code>（非零像素计数）</li><li><strong>保存</strong>：<code>saveMat(matId, path)</code> —— Mat 句柄保存为图片文件（自动创建父目录）</li><li><strong>回收</strong>：<code>recycle(matId)</code> / <code>clearMats()</code> —— 释放 Mat 池内存</li><li><strong>回收校验</strong>：<code>isRecycled(matId)</code> —— 判断 Mat 句柄是否已回收</li></ul><h2 id="接口清单" tabindex="-1">接口清单 <a class="header-anchor" href="#接口清单" aria-label="Permalink to &quot;接口清单&quot;">​</a></h2>',7)])])}const m=o(a,[["render",r]]);export{p as __pageData,m as default};
